#include <iostream>
#include <algorithm>
#include <array>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int INF = 1e9;
    array<int, 3> dp = {0, INF, INF};

    for (int i = 0; i < n; ++i) {
        int activity;
        cin >> activity;

        array<int, 3> next = {min({dp[0], dp[1], dp[2]}) + 1, INF, INF};

        if (activity == 1 || activity == 3)
            next[1] = min(dp[0], dp[2]);

        if (activity == 2 || activity == 3)
            next[2] = min(dp[0], dp[1]);

        dp = next;
    }

    cout << min({dp[0], dp[1], dp[2]});
    return 0;
}

